              <i class="fa-solid fa-rotate-right text-[10px]" :class="{ 'animate-spin': loading }"></i>
            </button>
          </div>

          <!-- Commit composer -->
          <div class="p-2 border-b border-base-content/10 flex flex-col gap-1.5 shrink-0">
